15	public class Simulator
16	{
17	    // Constants representing configuration information for the simulation.
18	    // The default width for the grid.
19	    private static final int DEFAULT_WIDTH = 150;
20	    // The default depth of the grid.
21	    private static final int DEFAULT_DEPTH = 100;
22	    // The probability that a human will be created in any given grid position.
23	    private static final double HUMAN_CREATION_PROBABILITY = 0.001;
24	    // The probability that a monkey will be created in any given grid position.
25	    private static final double MONKEY_CREATION_PROBABILITY = 0.04;
26	    // The probability that a pig will be created in any given grid position.
27	    private static final double PIG_CREATION_PROBABILITY = 0.06;
28	    // The probability that a tortoise will be created in any given grid position.
29	    private static final double TORTOISE_CREATION_PROBABILITY = 0.008;
30	    // The probability that a dodo will be created in any given grid position.
31	    private static final double DODO_CREATION_PROBABILITY = 0.5;    
32	    // The probability that a plant will be created in any given grid position.
33	    private static final double PLANT_CREATION_PROBABILITY = 0.9;
34	    // The probability that it is sunny.
35	    private static final double SUNNY_PROBABILITY = 0.55;
