37	    private static final double RAINY_PROBABILITY = 0.3;
38	    // The probability that it is foggy.
39	    private static final double FOGGY_PROBABILITY = 0.1;
40	    // The probability that it is snowing.
41	    private static final double SNOWY_PROBABILITY = 0.05;
