55	    // List of actors in the field.
56	    private List<Actor> actors;
57	    // The current state of the field.
58	    private Field field;
59	    // The current step of the simulation.
60	    private int step;
61	    // The number of steps the simulation will make
62	    private int numSteps;
63	    // The current weather of the simulation
64	    private Weather currentWeather;
65	    // The index of the time delay currently being used from the time delay list
66	    private int timeDelayIndex;
67	    // A graphical view of the simulation.
68	    private SimulatorView view;
69	    // Thread scheduler to control the number of threads the simulator can use
70	    private Executor executorService;
71	
