93	    /**
94	     * Create a simulation field with the given size.
95	     * 
96	     * @param depth Depth of the field. Must be greater than zero.
97	     * @param width Width of the field. Must be greater than zero.
98	     */
99	    public Simulator(int depth, int width)
100	    {
101	        if(width <= 0 || depth <= 0) {
102	            System.out.println("The dimensions must be greater than zero.");
103	            System.out.println("Using default values.");
104	            depth = DEFAULT_DEPTH;
105	            width = DEFAULT_WIDTH;
106	        }
107	
108	        executorService = new Executor(Runtime.getRuntime().availableProcessors());
109	        actors = new ArrayList<>();
110	        field = new Field(depth, width);
111	        this.numSteps = 0;
112	        // 1000 milliseconds
113	        timeDelayIndex = 2;
114	        // Random weather
115	        currentWeather = null;
116	
117	        // Create a view of the state of each location in the field.
118	        view = new SimulatorView(depth, width, this);
119	        view.setColor(Pig.class, new Color(255,102,102));
120	        view.setColor(Human.class, new Color(153,102,0));
121	        view.setColor(Dodo.class, new Color(255,204,51));
122	        view.setColor(Monkey.class, new Color(51,0,0));
123	        view.setColor(Tortoise.class, new Color(0,153,0));
124	        view.setColor(Plant.class, Color.GREEN);
125	
126	        // Setup a valid starting point.
127	        reset();
128	    }
