148	    /**
149	     * Run the simulation from its current state for the given number of steps.
150	     * Stop before the given number of steps if it ceases to be viable.
151	     * 
152	     * @param numSteps The number of steps to run for.
153	     */
154	    public void simulate(int numSteps)
155	    {   
156	        this.numSteps += numSteps;
157	        if(stopped){
158	            start();
159	            // executor service implementation for thread execution control
160	            executorService.scheduleWithFixedDelay(this::simulateStep, 0, 1, TimeUnit.NANOSECONDS);
161	        }
162	    }
163	
164	    /**
165	     * Runs method to simulate a single step if conditions met
166	     * Conditions: not paused, simulation steps not reached, executor open, field viable
167	     */
168	    private void simulateStep()
169	    {
170	        // simulates step if simulation should continue
171	        if(!paused && !stopped && view.isViable(field)){
172	            simulateOneStep();
173	            checkSimulationEnd();
174	            delay(timeDelayList.get(timeDelayIndex));
175	            return;
176	        }
177	
178	        if(stopped){
179	            System.out.println("The simulation has been stopped, add more steps to continue running");
180	        }
181	        if(paused){
182	            System.out.println("You've paused the simulation, unpause the simulation to continue running");
183	        }
184	        if (!view.isViable(field)) {
185	            System.out.println("The simulation has been stopped as there is one animal species left, reset the field to continue simulating");
186	        }
187	
188	        //pauses execution across all threads
189	        executorService.pause();
190	    }
