192	    /**
193	     * Simulates one step if paused
194	     * Cannot simulate a step if simulation is running
195	     */
196	    public void forceSimulateOneStep()
197	    {
198	        if(paused || stopped){
199	            simulateOneStep();
200	        }
201	        else{
202	            System.out.println("Pause simulation to use this function");
203	        }
