206	    /**
207	     * Run the simulation from its current state for a single step
208	     * Iterate over the whole field updating the state of each actor
209	     */
210	    private void simulateOneStep() 
211	    {
212	        step++;
213	
214	        // Provide space for newborn actors.
215	        List<Actor> newActors = new ArrayList<>();
216	        // Stores dead actors to be removed from actors.
217	        HashSet<Actor> deadActors = new HashSet<>();
218	        // Changes weather every step
219	        Weather weather = getWeather();
220	        // list of infected actors
221	        ArrayList<Actor> infected = new ArrayList<>();
222	
223	        // Let all actors act.
224	        actors.forEach(actor -> {
225	                actor.act(newActors, step % 2, weather);
226	                if (!actor.isAlive()) {
227	                    deadActors.add(actor);
228	                } 
229	                // gets number of infected animals
230	                else if (actor.getInfected()) {
231	                    infected.add(actor);
232	                }
233	            });
234	
235	        // Removes dead actors to actors list
236	        deadActors.forEach(actor -> actors.remove(actor));
237	
238	        // Adds new actors to actors list
239	        newActors.forEach(actor -> actors.add(actor));
240	
241	        if (step > numSteps) {
242	            numSteps = step + 1;
243	        }
244	
245	        view.showStatus(step, numSteps, field, weather, infected.size());
246	    }
247	
248	    /**
249	     * Reset the simulation to a starting position.
250	     */
251	    public void reset()
252	    {
253	        // resets step counter
254	        step = 0;
255	        numSteps = 0;
256	        // stops simulator
257	        stopped = true;
258	        // removes actors in simulation
259	        actors.clear();
260	        // repopulates simulation
261	        int infected = populate();
262	        // resets simulation speed
263	        timeDelayIndex = 2;
264	        // resets current weather to random
265	        currentWeather = null;
266	
267	        Weather weather = getWeather();
268	
269	        // Show the starting state in the view.
270	        view.showStatus(step, numSteps, field, weather, infected);
271	    }
