273	    /**
274	     * Randomly populate the field with actors.
275	     */
276	    private int populate()
277	    {
278	        Random rand = Randomizer.getRandom();
279	        field.clear();
280	
281	        //Gathers running probability for use in creation
282	        double[] totalProbabilities = {DODO_CREATION_PROBABILITY, HUMAN_CREATION_PROBABILITY, PIG_CREATION_PROBABILITY, MONKEY_CREATION_PROBABILITY, TORTOISE_CREATION_PROBABILITY};
283	        totalProbabilities =  getTotalProbability(totalProbabilities);
284	
285	        //number of infected actors
286	        int infected = 0;
287	
288	        for(int row = 0; row < field.getDepth(); row++) {
289	            for(int col = 0; col < field.getWidth(); col++) {
290	                // Populate with animals and plants as per their probabilities    
291	                Location location = new Location(row, col);
292	                boolean virus = false;
293	
294	                if (rand.nextDouble() <= DISEASE_CREATION_PROBABILITY) {
295	                    virus = true;
296	                    ++infected;
297	                }
298	
299	                if (rand.nextDouble() <= PLANT_CREATION_PROBABILITY) {
300	                    Plant plant = new Plant(true, field, location);
301	                    actors.add(plant);
302	                }
303	
304	                if (rand.nextDouble() <= totalProbabilities[0]){
305	                    Dodo dodo = new Dodo(true, field, location, virus);
306	                    actors.add(dodo);
307	                }
308	                else if(rand.nextDouble() <= totalProbabilities[1]){
309	                    Human human = new Human(true, field, location, virus);
310	                    actors.add(human);
311	                }
312	                else if(rand.nextDouble() <= totalProbabilities[2]){
313	                    Pig pig = new Pig(true, field, location, virus);
314	                    actors.add(pig);
315	                }
316	                else if (rand.nextDouble() <= totalProbabilities[3]){
317	                    Monkey monkey = new Monkey(true, field, location, virus);
318	                    actors.add(monkey);
319	                }
320	                else if (rand.nextDouble() <= totalProbabilities[4]){
321	                    Tortoise tortoise = new Tortoise( true, field, location, virus);
322	                    actors.add(tortoise);
323	                }
324	            }
325	        }
326	
327	        // Gives warning if spawn probability is above 1
328	        if(totalProbabilities[totalProbabilities.length-1] > 1){
329	            System.out.println("Your total spawn probability is above 1, there may be some unexpected errors in simulation as a result");
330	        }
331	
332	        return infected;
333	    }
334	
335	    /**
336	     * Generates running total probability list based on input
337	     * 
338	     * @param total Probability list
339	     * @return Running total probability list
340	     */
341	    private double[] getTotalProbability(double[] total)
342	    {
343	        for(int i=0; i < total.length-1; i++){
344	            total[i+1]+=total[i];
345	        }
346	
347	        return total;
348	    }
349	
350	    /**
351	     * Checks if the simulation should be ended
352	     * Dictated by the number of sets set to be shown
353	     */
354	    private void checkSimulationEnd()
355	    {
356	        if(numSteps == step){
357	            stopSimulation();
358	        }
359	    }
