361	    /**
362	     * Sets stopped and paused to false
363	     */
364	    private void start()
365	    {
366	        stopped = false;
367	        paused = false;
368	
369	        // resumes execution across all threads
370	        executorService.resume();
371	    }
372	
373	    /**
374	     * Stops the current simulation
375	     */
376	    private void stopSimulation()
377	    {
378	        stopped = true;
379	    }
380	
