391	    /**
392	     * Sets paused value of simulation
393	     */
394	    public void setPauseSimulation(boolean pause) 
395	    {
396	        if(pause == paused){
397	            if(paused){
398	                System.out.println("Simulator already paused");
399	            }
400	            else{
401	                System.out.println("Simulator already playing");
402	            }
403	        }
404	
405	        paused = pause;
406	
407	        if(!pause){
408	            // resumes execution across all threads
409	            executorService.resume();
410	        }
