412	
413	    /**
414	     * Allows users to switch the current weather conditions
415	     * null if random
416	     * 
417	     * @param weather The weather to be changed to, null if random
418	     */
419	    public void setCurrentWeather(Weather weather)
420	    {
421	        if(weather != null && currentWeather != null && this.currentWeather.equals(weather)){
422	            System.out.println("The weather is already set to " + currentWeather);
423	            return;
424	        }
425	        if(weather == null && currentWeather==null){
426	            System.out.println("The weather is already set to random");
427	            return;
428	        }
429	
430	        this.currentWeather = weather;
431	    }
432	
433	    /***
434	     * Returns the current weather conditions of the simulation
435	     * Random if null
436	     *  
437	     * @return The current weather conditions of the simulation
438	     */
439	    private Weather getWeather()
440	    {
441	        if(currentWeather == null){
442	            return randomWeather();
443	        }
444	        else{
445	            return currentWeather;
446	        }
447	    }
448	
449	    /**
450	     * Generates a random weather from the Weather ENUM
451	     */
452	    private Weather randomWeather() 
453	    {
454	        Random rand = Randomizer.getRandom();
455	
456	        double[] totalProbabilities = {SNOWY_PROBABILITY, FOGGY_PROBABILITY, RAINY_PROBABILITY, SUNNY_PROBABILITY};
457	        totalProbabilities =  getTotalProbability(totalProbabilities);
458	
459	        if (rand.nextDouble() <= totalProbabilities[0]){
460	            return Weather.SNOWY;
461	        }
462	        else if (rand.nextDouble() <= totalProbabilities[1]){
463	            return Weather.FOGGY;
464	        }
465	        else if (rand.nextDouble() <= totalProbabilities[2]){
466	            return Weather.RAINY;
467	        }
468	        else if (rand.nextDouble() <= totalProbabilities[3]){
469	            return Weather.SUNNY;
470	        }
471	
472	        if (totalProbabilities[totalProbabilities.length-1] != 1) {
473	            System.out.println("Your total weather probability is not equal to 1, there may be some unexpected errors in simulation as a result");
474	        }
475	
476	        return Weather.SUNNY;
477	    }
