479	    /**
480	     * Pause for a given time.
481	     * 
482	     * @param millisec The time to pause for, in milliseconds
483	     */
484	    private void delay(int millisec) 
485	    {
486	        try {
487	            Thread.sleep(millisec);
488	        } catch (InterruptedException ie) {
489	            // wake up
490	        }
491	    }
492	
493	    /**
494	     * Returns the field used in the current simulation
495	     * 
496	     * @return The field used in the current simulation
497	     */
498	    public Field getField()
499	    {
500	        return field;
501	    }
