7	/**
8	 * A class representing shared characteristics of animals.
9	 *
10	 * @version (28/02/2022)
11	 */
12	public abstract class Animal extends Actor
13	{
14	    // The animal's gender.
15	    private Gender gender;
16	    // The animal's age.
17	    protected int age;
18	    // The animal's food level, which is increased by eating.
19	    protected double foodLevel;
20	    // The base rate which is used to give
21	    // the number of steps a predator gains when it eats this animal.
22	    private int FOOD_VALUE;
23	    // The probability that a predator eats its prey.
24	    private static final double EATING_PROBABILITY = 0.8;
25	    // A map containing values that can affect how the animal reacts based off the weather.
26	    private EnumMap<WeatherEffectTypes, Double> weatherEffect = new EnumMap<>(WeatherEffectTypes.class);
27	    // Probability that an animal dies from disease.
28	    private double DEATH_FROM_DISEASE_PROBABILITY;
29	    // Minimum breeding age.
30	    private int BREEDING_AGE;
31	    // Probability of successful breeding when a partner is found.
32	    private double BREEDING_PROBABILITY;
33	    // Maximum litter per breeding session.
34	    private int MAX_LITTER_SIZE;
35	    // Maximum age the animal can reach.
36	    private int MAX_AGE;
37	    // Probability that an infected animal spreads the virus.
38	    private double VIRUS_SPREAD_PROBABILITY = 0.1;
39	    // The probability that an infected animal gets cured.
40	    private double CURE_INFECTION_PROBABILITY = 0.1;
41	    // Map containing a set of all the predators of a given animal.
42	    protected static HashMap<Class, HashSet<Class>> MAP_OF_PREDATORS =  new HashMap<>();
43	
44	    // Whether an animal is infected by disease or not.
45	    protected boolean infected;
46	
47	    /**
48	     * Create a new animal at location in field.
49	     * 
50	     * @param field    The field currently occupied.
51	     * @param location The location within the field.
52	     * @param infected Boolean value determining if the animal is infected or not.
53	     * 
54	     */
55	    protected Animal(Field field, Location location, boolean infected)
56	    {
57	        super(field, location);
58	        // infects animal if infected.
59	        this.infected = infected;
60	        // assigns random gender.
61	        randomGender();
62	        initiatePredators();
63	    }
64	
65	    /**
66	     * Creates a key for the current animal type in the MAP_OF_PREDATORS.
67	     * Generates empty set and assigns it to the key.
68	     */
69	    private void initiatePredators()
70	    {
71	        if(!MAP_OF_PREDATORS.containsKey(this.getClass())){
72	            MAP_OF_PREDATORS.put(this.getClass(), new HashSet<Class>());
73	        }
74	    }
75	
76	    /**
77	     * Sets the maximum age of the animal.
78	     * 
79	     * @param maxAge THe maximum age of the animal.
80	     */
81	    protected void setMaxAge(int maxAge)
82	    {
83	        MAX_AGE = maxAge;
84	    }
85	
86	    /**
87	     * Sets the minimum age the animal can start breeding.
88	     * 
89	     * @param setBreedingAge The minimum age the animal can start breeding.
90	     */
91	    protected void setBreedingAge(int breedingAge)
92	    {
93	        BREEDING_AGE = breedingAge;
94	    }
95	
96	    /**
97	     * Sets the breeding probability of the animal.
98	     * 
99	     * @param breedingProbability The breeding probability of the animal.
100	     */
101	    protected void setBreedingProbability(double breedingProbability) 
102	    {
103	        BREEDING_PROBABILITY = breedingProbability;
104	    }
105	
106	    /**
107	     * Sets the maximum litter per breeding period for an animal.
108	     * 
109	     * @param maxLitter The maximum litter per breeding period for an animal.
110	     */
111	    protected void setMaxLitter(int maxLitter) 
112	    {
113	        MAX_LITTER_SIZE = maxLitter;
114	    }
115	
116	    /**
117	     * Sets the gender of the animal.
118	     * 
119	     * @param setGender The gender that the animal will be set to.
120	     */
121	    private void setGender(Gender gender) 
122	    {
123	        this.gender = gender;
124	    }
125	
126	    /**
127	     * Sets the base number of steps predator gains for eating this animal.
128	     * 
129	     * @param foodValue The base step number.
130	     */
131	    protected void setFoodValue(int foodValue)
132	    {
133	        FOOD_VALUE = foodValue;
134	    }
135	
136	    /**
137	     * Generates a random gender from the Gender ENUM.
138	     * Call setGender to give animal this random gender.
139	     */
140	    private void randomGender()
141	    {
142	        setGender(Gender.values()[rand.nextInt(Gender.values().length)]);
143	    }            
144	
145	    /**
146	     * Gets the gender of the animal.
147	     * 
148	     * @return Gender of the animal.
149	     */
150	    private Gender getGender()
151	    {
152	        return gender;
153	    }
154	
155	    /**
156	     * Retrieves and sets the current weather effect values.
157	     */
158	    protected void setWeatherEffects() 
159	    {
160	        weatherEffect = WeatherAction.weatherOnAnimals(weather);
161	    }
162	
163	    /**
164	     * An animal can breed if it has reached the breeding age and meets a mate of opposite gender.
165	     * 
166	     * @param field The field the object is in.
167	     * @return Boolean value, true if mate is found and is of age, false otherwise.
168	     */
169	    private boolean canBreed(Field field) 
170	    {
171	        // Find all adjacent locations.
172	        List<Location> adjacentLocations = field.adjacentLocations(getLocation()); 
173	        // List of potential partners.
174	        List<Animal> partnerList = new ArrayList<>();
175	
176	        adjacentLocations.forEach(adjacentLocation -> {
177	                Object actor = field.getObjectAt(adjacentLocation);
178	                if (actor instanceof Animal) {
179	                    Animal animal = (Animal) actor;
180	                    // Check for same species and opposite gender.
181	                    if (this.getClass().equals(animal.getClass()) && !(this.getGender().equals(animal.getGender()))) {
182	                        partnerList.add(animal);
183	                    }
184	                }
185	            });
186	
187	        return age >= BREEDING_AGE && !partnerList.isEmpty();
188	    }
189	
190	    /**
191	     * Increase the age. This could result in the animal's death.
192	     */
193	    protected void incrementAge() 
194	    {
195	        age++;
196	        if (age > MAX_AGE) {
197	            setDead();
198	        }
199	    }
200	
