20	    private static final double BREEDING_PROBABILITY = 0.9;
21	    // The maximum number of births.
22	    private static final int MAX_LITTER_SIZE = 12;
23	    // The base rate which is used to give
24	    // the number of steps a predator gains when it eats a dodo
25	    private static final int BASIC_FOOD_LEVEL = 8;
26	    // The chance of a Dodo attacking a predator in its sleep
27	    private static final double ATTACK_CHANCE = 0.01;
28	    // Probability that a dodo dies from disease.
29	    private static final double DODO_DEATH_FROM_DISEASE_PROBABILITY = 0.005;
30	    // List of all dodo prey.
31	    private final ArrayList<Class> LIST_OF_PREY = new ArrayList<>() {
32	            {
33	                add(Plant.class);
34	            }
35	        };
36	
37	    /**
38	     * Create a dodo. A dodo can be created as a new born (age zero
39	     * and not hungry) or with a random age and food level.
40	     * 
41	     * @param randomAge If true, the dodo will have random age and hunger level.
42	     * @param field     The field currently occupied.
43	     * @param location  The location within the field.
44	     * @param infected  Boolean value determining if the animal is infected or not
45	     */
46	    protected Dodo(boolean randomAge, Field field, Location location, boolean infected)
47	    {
48	        super(field, location, infected);
49	
50	        // Sets values in animal class
51	        setOverlap(false);
52	        setFoodValue(BASIC_FOOD_LEVEL);
53	        setDeathByDiseaseProbability(DODO_DEATH_FROM_DISEASE_PROBABILITY);
54	        setBreedingAge(BREEDING_AGE);
55	        setBreedingProbability(BREEDING_PROBABILITY);
56	        setMaxLitter(MAX_LITTER_SIZE);
57	        setMaxAge(MAX_AGE);
58	
59	        if(randomAge) {
60	            age = rand.nextInt(MAX_AGE);
61	            foodLevel = rand.nextInt(BASIC_FOOD_LEVEL);
62	        }
63	        else {
64	            age = 0;
65	            foodLevel = BASIC_FOOD_LEVEL;
66	        }
67	    }
