69	    /**
70	     * This is what the dodo does during the day: it looks for plants and tries to breed
71	     * In the process it might move, die of hunger, die of infection, get cured, spread an infection, or die of old age.
72	     * 
73	     * @param newDodos A list to return newly born Dodos.
74	     */
75	    protected void dayAct(List<Actor> newDodos)
76	    {
77	        incrementAge();
78	        incrementHunger();
79	        dieInfection();
80	
81	        if(isAlive()) {            
82	            giveBirth(newDodos);   
83	            cureInfected();
84	            spreadVirus();
85	
86	            // Move towards a source of food if found.
87	            Location newLocation = super.findFood(LIST_OF_PREY);
88	            if(newLocation == null) { 
89	                // No food found - try to move to a free location.
90	                newLocation = getField().freeAdjacentLocation(getLocation());
91	            }
92	            // See if it was possible to move.
93	            if(newLocation != null) {
94	                setLocation(newLocation);
95	            }
96	            else {
97	
98	                // Overcrowding.
99	                setDead();
100	            }
101	        }
102	    }
