104	    /**
105	     * This is what the dodos do during the night:  Sleeps and Attacks predators
106	     * In the process it might, die of infection or spread an infection
107	     * 
108	     * @param newDodos A list to return newly born Dodos.
109	     */
110	    protected void nightAct(List<Actor> newDodos)
111	    {
112	
113	        dieInfection();
114	
115	        if (isAlive()) {
116	            cureInfected();
117	            spreadVirus();
118	
