128	     * Dodo's attack their known predators
129	     * Looks at all adjacent locations, and attacks first predator found
130	     * Dodo moves into the position the predator was
131	     */
132	    private Location chargePredator()
133	    {
134	        Field field = getField();
135	        List<Location> adjacent = field.adjacentLocations(getLocation());
136	        List<Location> charge = new ArrayList<>();
137	
138	        adjacent.forEach(where ->{
139	                Object actor = field.getObjectAt(where);
140	                HashSet<Class> setOfPredators = MAP_OF_PREDATORS.get(this.getClass());
141	                if(actor!=null && setOfPredators.contains(actor.getClass())){
142	                    if(rand.nextDouble() <= ATTACK_CHANCE){
143	                        Animal prey = (Animal) actor;
