11	 */
12	public class Field
13	{   
14	    // A random number generator for providing random locations.
15	    private static final Random rand = Randomizer.getRandom();
16	
17	    // The depth and width of the field.
18	    private int depth, width;
19	    // Storage for the actors.
20	    private Object[][] field;
21	
22	    /**
23	     * Represent a field of the given dimensions.
24	     * 
25	     * @param depth The depth of the field.
26	     * @param width The width of the field.
27	     */
28	    public Field(int depth, int width)
29	    {
30	        this.depth = depth;
31	        this.width = width;
32	        field = new Object[depth][width];
33	    }
34	
35	    /**
36	     * Empty the field.
37	     */
38	    public void clear()
39	    {
40	        for(int row = 0; row < depth; row++) {
41	            for(int col = 0; col < width; col++) {
42	                field[row][col] = null;
43	            }
44	        }
45	    }
46	
47	    /**
48	     * Clear the given location.
49	     * 
50	     * @param location The location to clear.
51	     */
52	    public void clear(Location location)
53	    {
54	        field[location.getRow()][location.getCol()] = null;
55	    }
56	
57	    /**
58	     * Place an actor at the given location.
59	     * If there is already an actor at the location it will be lost.
60	     * Animals cannot be overwritten by other actors except for by another animal
61	     * 
62	     * @param actor The actor to be placed.
63	     * @param row Row coordinate of the location.
64	     * @param col Column coordinate of the location.
65	     */
66	    public void place(Object actor, int row, int col)
