395	    public void showStatus(int step, int totalSteps, Field field, Weather weather, int virusCount)
396	    {
397	        if(!isVisible()) {
398	            setVisible(true);
399	        }
400	
401	        // Displays day number.
402	        stepLabel.setText(DAY_PREFIX + (step+1)/2 + "/" + totalSteps/2);
403	        // Computes and displays time of day.
404	        String time = "";
405	        if(step%2 == 0){
406	            time = "Night";
407	        }
408	        else if(step%2 == 1){
409	            time = "Day";
410	        }
