421	     * Clears and repaints the field on the viewer.
422	     * 
423	     * @param field The field the viewer is currently representing.
424	     * @param newStep Defines whether a new step has occured or not.
425	     */
426	    private void updatePanel(Field field, boolean newStep)
427	    {
428	        fieldView.preparePaint();
429	
430	        for (int row = 0; row < field.getDepth(); row++) {
431	            for (int col = 0; col < field.getWidth(); col++) {
432	                Actor actor = (Actor) field.getObjectAt(row, col);
433	                if (actor != null) {
434	                    // Increments population
435	                    if(newStep){
436	                        stats.incrementCount(actor.getClass()); 
437	                    }
438	                    fieldView.drawMark(col, row, getColor(actor.getClass()));
439	                } else {
440	                    fieldView.drawMark(col, row, EMPTY_COLOR);
441	                }
442	            }
443	        }
444	        stats.countFinished();
445	
446	        population.setText(POPULATION_PREFIX + stats.getPopulationDetails(field));
447	        fieldView.repaint();
448	    }
