461	    /**
462	     * Provide a graphical view of a rectangular field. This is 
463	     * a nested class (a class defined inside a class) which
464	     * defines a custom component for the user interface. This
465	     * component displays the field.
466	     * This is rather advanced GUI stuff - you can ignore this 
467	     * for your project if you like.
468	     */
469	    private class FieldView extends JPanel
470	    {
471	        private final int GRID_VIEW_SCALING_FACTOR = 6;
472	
473	        private int gridWidth, gridHeight;
474	        private int xScale, yScale;
475	        Dimension size;
476	        private Graphics g;
477	        private Image fieldImage;
478	
479	        /**
480	         * Create a new FieldView component.
481	         * 
482	         * @param height The height of the field.
483	         * @param width The width of the field.
484	         */
485	        public FieldView(int height, int width)
486	        {
487	            gridHeight = height;
488	            gridWidth = width;
489	            size = new Dimension(0, 0);
490	        }
491	
492	        /**
493	         * Tell the GUI manager how big we would like to be.
494	         * 
495	         * @return The field size.
496	         */
497	        @Override
498	        public Dimension getPreferredSize()
499	        {
500	            return new Dimension(gridWidth * GRID_VIEW_SCALING_FACTOR,
501	                gridHeight * GRID_VIEW_SCALING_FACTOR);
502	        }
503	
504	        /**
505	         * Prepare for a new round of painting. Since the component
506	         * may be resized, compute the scaling factor again.
507	         */
508	        public void preparePaint()
509	        {
510	            if(! size.equals(getSize())) {  // if the size has changed...
511	                size = getSize();
512	                fieldImage = fieldView.createImage(size.width, size.height);
513	                g = fieldImage.getGraphics();
514	
515	                xScale = size.width / gridWidth;
516	                if(xScale < 1) {
517	                    xScale = GRID_VIEW_SCALING_FACTOR;
518	                }
519	                yScale = size.height / gridHeight;
520	                if(yScale < 1) {
521	                    yScale = GRID_VIEW_SCALING_FACTOR;
522	                }
523	            }
524	        }
525	
526	        /**
527	         * Paint on grid location on this field in a given color.
528	         * 
529	         * @param x The x-coordinate in the field.
530	         * @param y The y-coordinate in the field.
531	         * @param color The color to be painted on the field.
532	         */
533	        public void drawMark(int x, int y, Color color)
534	        {
535	            g.setColor(color);
536	            g.fillRect(x * xScale, y * yScale, xScale-1, yScale-1);
537	        }
538	
539	        /**
540	         * The field view component needs to be redisplayed. Copy the
541	         * internal image to screen.
542	         * 
543	         * @param g An object of the Graphics class.
544	         */
545	        @Override
546	        public void paintComponent(Graphics g)
547	        {
548	            if(fieldImage != null) {
549	                Dimension currentSize = getSize();
550	                if(size.equals(currentSize)) {
551	                    g.drawImage(fieldImage, 0, 0, null);
552	                }
553	                else {
554	                    // Rescale the previous image.
555	                    g.drawImage(fieldImage, 0, 0, currentSize.width, currentSize.height, null);
556	                }
557	            }
558	        }
559	    }
560	}
