                }
            });

        rainyButton = new JButton("Rainy Weather");
        rainyButton.addActionListener(new ActionListener() {
                public void actionPerformed(ActionEvent e) {
                    simulator.setCurrentWeather(Weather.RAINY);
                }
            });

