import java.util.*;

/**
 * Headless A/B regression driver. Mirrors Simulator.populate() and
 * simulateOneStep() without the Swing GUI, then prints a deterministic
 * signature of the field population so the baseline and refactored builds
 * can be compared byte-for-byte.
 */
public class Driver
{
    static final double HUMAN = 0.001, MONKEY = 0.04, PIG = 0.06, TORTOISE = 0.008, DODO = 0.5;
    static final double PLANT = 0.9, DISEASE = 0.05;

    static double[] running(double[] t) {
        for (int i = 0; i < t.length - 1; i++) t[i + 1] += t[i];
        return t;
    }

    public static void main(String[] args) {
        int depth = 40, width = 30, steps = 60;
        Field field = new Field(depth, width);
        List<Actor> actors = new ArrayList<>();
        Random rand = Randomizer.getRandom();
        field.clear();
        double[] p = running(new double[]{DODO, HUMAN, PIG, MONKEY, TORTOISE});

        for (int row = 0; row < depth; row++) {
            for (int col = 0; col < width; col++) {
                Location loc = new Location(row, col);
                boolean virus = rand.nextDouble() <= DISEASE;
                if (rand.nextDouble() <= PLANT) actors.add(new Plant(true, field, loc));
                if (rand.nextDouble() <= p[0]) actors.add(new Dodo(true, field, loc, virus));
                else if (rand.nextDouble() <= p[1]) actors.add(new Human(true, field, loc, virus));
                else if (rand.nextDouble() <= p[2]) actors.add(new Pig(true, field, loc, virus));
                else if (rand.nextDouble() <= p[3]) actors.add(new Monkey(true, field, loc, virus));
                else if (rand.nextDouble() <= p[4]) actors.add(new Tortoise(true, field, loc, virus));
            }
        }

        int step = 0;
        for (int s = 0; s < steps; s++) {
            step++;
            List<Actor> newActors = new ArrayList<>();
            HashSet<Actor> dead = new HashSet<>();
            Weather weather = Weather.values()[step % Weather.values().length];
            for (Actor a : actors) {
                a.act(newActors, step % 2, weather);
                if (!a.isAlive()) dead.add(a);
            }
            dead.forEach(actors::remove);
            actors.forEach(a -> {});
            newActors.forEach(actors::add);
        }

        // Deterministic signature: counts per class on the field grid.
        TreeMap<String, Integer> counts = new TreeMap<>();
        for (int row = 0; row < depth; row++)
            for (int col = 0; col < width; col++) {
                Object o = field.getObjectAt(row, col);
                if (o != null) counts.merge(o.getClass().getSimpleName(), 1, Integer::sum);
            }
        System.out.println("actorsList=" + actors.size() + " field=" + counts);
    }
}

